import{_ as p,a0 as d,w as o,s as r,I as a,x as e,a1 as n,A as l,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"在 FreeDOS 中使用批處理文件 | LCTT x X-CMD","titleTemplate":false,"description":"在 FreeDOS 中使用批處理文件 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 FreeDOS 中使用批處理文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 FreeDOS 中使用批處理文件 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210407 Get started with batch files in FreeDOS","title":"在 FreeDOS 中使用批處理文件","tag":"202112","desc":""},"relativePath":"202112/20210407 Get started with batch files in FreeDOS.md","filePath":"[post].md"}'),h={name:"202112/20210407 Get started with batch files in FreeDOS.md"};function c(g,s,k,b,u,T){const i=d("Link");return o(),r("div",null,[s[27]||(s[27]=a("h1",{id:"在-freedos-中使用批處理文件",tabindex:"-1"},[e("在 FreeDOS 中使用批處理文件 "),a("a",{class:"header-anchor",href:"#在-freedos-中使用批處理文件","aria-label":"Permalink to “在 FreeDOS 中使用批處理文件”"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"編寫你自己的簡單程序來自動執行通常需要大量輸入的任務的批處理文件，是一種極好的方法。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202112/24/102751sldikuebf7z4u64l.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在 Linux 上，創建 ",-1)),s[2]||(s[2]=a("em",null,"shell 腳本",-1)),s[3]||(s[3]=e(" 來自動執行重複的任務是很常見的。類似地，在開源版的舊式 DOS 操作系統 ",-1)),n(i,{href:"https://www.freedos.org/"},{default:l(()=>[...s[0]||(s[0]=[e("FreeDOS",-1)])]),_:1}),s[4]||(s[4]=e(" 上，你可以創建一個包含數個 FreeDOS 命令的 ",-1)),s[5]||(s[5]=a("em",null,"批處理文件",-1)),s[6]||(s[6]=e(" 。然後，你就可以運行你的批處理文件來按順序執行每個命令。",-1))]),s[30]||(s[30]=t('<p>你可以使用一個 ASCII 文本編輯器來創建批處理文件，諸如 FeeDOS 的 Edit 應用程序。在你創建一個批處理文件後，你可以使用一個文件名稱加上擴展名 <code>.bat</code> 來保存它。文件名稱應該是唯一的。如果你使用 FreeDOS 的一個命令的名稱作為你自己的文件名稱，那麼可能將會執行 FreeDOS 的命令，而不會是你的批處理文件。</p><p>實際上，所有的內部的和外部的 FreeDOS 命令都可以在一個批處理文件中使用。在你創建一個批處理文件時，你其實就是在編寫一個程序。FreeDOS 批處理文件可能沒有結構化編程語言的功能，但是對於耗時短暫卻重複乏味的任務來説，它是非常方便的。</p><h3 id="註釋你的代碼" tabindex="-1">註釋你的代碼 <a class="header-anchor" href="#註釋你的代碼" aria-label="Permalink to “註釋你的代碼”">​</a></h3><p>對於任何程序員來説，學習的第一個好習慣都應該是：在一個程序中放置註釋來解釋該代碼正在做什麼。這是一件非常容易完成的事情，但是你需要仔細，不要傻傻地讓操作系統來執行你的註釋。避免出現這種情況的方法是在一個註釋行的開頭處放置 <code>REM</code>（“remark” 的縮寫） 。</p><p>FreeDOS 忽略以 <code>REM</code> 開頭的代碼行。但是任何查看源文件代碼（即你在你的批處理文件中所編寫的文本）的人都可以讀取你的註釋並理解它在做什麼。這也是一種臨時性禁用一個命令而不需要刪除它的一種方法。只需要打開你的批處理文件來進行編輯，在你想要禁用行的開頭處放置 <code>REM</code> ，並保存它。在你想要重新啓用這個命令時，只需要打開文件來進行編輯和移除 <code>REM</code> 。這種技巧有時被稱為 “註釋掉” 一個命令。</p><h3 id="開始設置" tabindex="-1">開始設置 <a class="header-anchor" href="#開始設置" aria-label="Permalink to “開始設置”">​</a></h3>',6)),a("p",null,[s[8]||(s[8]=e("在你開始編寫你自己的批處理文件前，我建議在 FreeDOS 中創建一個臨時目錄。這將會為你提供一個處理批處理文件的安全空間，不會意外地刪除、移動，或重命名重要的系統文件或目錄。在 FreeDOS 上，你可以使用 ",-1)),s[9]||(s[9]=a("code",null,"MD",-1)),s[10]||(s[10]=e(" 命令來 ",-1)),n(i,{href:"https://opensource.com/article/21/2/freedos-commands-you-need-know"},{default:l(()=>[...s[7]||(s[7]=[e("創建一個目錄",-1)])]),_:1}),s[11]||(s[11]=e(" ：",-1))]),s[31]||(s[31]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;MD TEMP</span></span>
<span class="line"><span>C:\\&gt;CD TEMP</span></span>
<span class="line"><span>C:\\TEMP&gt;</span></span></code></pre></div><p>FreeDOS 的 <code>ECHO</code> 命令會控制當你運行一個批處理文件時在屏幕上顯示的東西。例如，這裏是一個簡單是單行批處理文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ECHO Hello world</span></span></code></pre></div><p>如果你創建這個文件並運行它，你將看到在屏幕上顯示的句子。從命令列中完成這項操作的最快的方法是：使用 <code>COPY</code> 命令來從你的鍵盤中（<code>CON</code>）獲取輸入，並將其放置到文件 <code>TEST1.BAT</code> 之中。接下來，按下組合鍵 <code>Ctrl+Z</code> 來停止複製過程，按下你鍵盤上的 <code>Return</code> 或 <code>Enter</code> 按鍵來返回一個提示。</p><p>在你的臨時目錄中嘗試創建這個文件為 <code>TEST1.BAT</code> ，接下來運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;COPY CON TEST1.BAT</span></span>
<span class="line"><span>CON =&gt; TEST1.BAT</span></span>
<span class="line"><span>ECHO Hello world</span></span>
<span class="line"><span>^Z</span></span>
<span class="line"><span></span></span>
<span class="line"><span>C:\\TEMP&gt;TEST1</span></span>
<span class="line"><span>Hello world</span></span></code></pre></div><p>當你想要顯示一段文本時，這可能很有用。例如，在一個程序完成它的任務時，你可能會在你的屏幕上看到一條告訴你需要等待的消息，或者在一個網絡環境中時，你可能會看到一條登錄消息。</p><p>如果你想要顯示一個空行怎麼辦？你可能會認為 <code>ECHO</code> 命令本身就可以達到目的，但是單獨一個 <code>ECHO</code> 命令只會詢問 FreeDOS 來響應 <code>ECHO</code> 是打開還是關閉：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;ECHO</span></span>
<span class="line"><span>ECHO is on</span></span></code></pre></div><p>獲取一個空白行的方法是在 <code>ECHO</code>後緊接着使用一個 <code>+</code>符號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;ECHO+</span></span>
<span class="line"><span></span></span>
<span class="line"><span>C:\\TEMP&gt;</span></span></code></pre></div><h3 id="批處理文件變量" tabindex="-1">批處理文件變量 <a class="header-anchor" href="#批處理文件變量" aria-label="Permalink to “批處理文件變量”">​</a></h3><p>變量是一個存儲你需要你的批處理文件臨時記住的信息的位置。這是編程的一個重要的功能，因為你不能總是知道你的批處理文件需要使用什麼樣的數據。這裏有一個用於演示的簡單示例。</p><p>創建 <code>TEST3.BAT</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@MD BACKUPS</span></span>
<span class="line"><span>COPY %1 BACKUPS\\%1</span></span></code></pre></div><p>變量是使用百分比符號和隨後的數字表示的，因此，這個批處理文件將在你的當前目錄中創建一個 <code>BACKUPS</code> 子目錄，然後將複製變量 <code>%1</code> 到 <code>BACKUPS</code> 文件夾之中。這個變量是什麼？當你運行批處理文件時，變量由你決定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;TEST3 TEMP1.BAT</span></span>
<span class="line"><span>TEST1.BAT =&gt; BACKUPS\\TEST1.BAT</span></span></code></pre></div><p>你的批處理文件已經複製 <code>TEST1.BAT</code> 到一個名稱為 <code>BACKUPS</code> 的子目錄，因為在你運行批處理文件時，你標識這個文件為一個參數。你的批處理文件將把 <code>%1</code> 替換為 <code>TEST1.BAT</code> 。</p><p>變量是按位置的。變量 <code>%1</code> 是你提供給命令的第一個參數，變量 <code>%2</code> 是第二個參數，以此類推。假設你創建一個批處理文件來列出一個目錄的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DIR %1</span></span></code></pre></div><p>嘗試運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;TEST4.BAT C:\\HOME</span></span>
<span class="line"><span>ARTICLES</span></span>
<span class="line"><span>BIN</span></span>
<span class="line"><span>CHEATSHEETS</span></span>
<span class="line"><span>GAMES</span></span>
<span class="line"><span>DND</span></span></code></pre></div><p>這像預期一樣的工作。但是下面這個卻失敗了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;TEST4.BAT C:\\HOME C:\\DOCS</span></span>
<span class="line"><span>ARTICLES</span></span>
<span class="line"><span>BIN</span></span>
<span class="line"><span>CHEATSHEETS</span></span>
<span class="line"><span>GAMES</span></span>
<span class="line"><span>DND</span></span></code></pre></div><p>如果你嘗試它，你將得到第一個參數（<code>C:\\HOME</code>）的列表，而得不到第二個參數（<code>C:\\DOCS</code>）的列表。這是因為你的批處理文件僅查找一個變量（<code>%1</code>），此外，<code>DIR</code> 命令也僅能獲取一個目錄。</p><p>此外，當你運行一個批處理文件時，你也不需要為其具體指定擴展名 —— 除非你運氣相當不好地為批處理文件選取了一個與 FreeDOS 外部命令或類似命令相同的名稱。當 FreeDOS 執行命令時，它按下面的順序執行：</p><ol><li>內部命令</li><li>帶有 *.COM 擴展名的外部命令</li><li>帶有 *.EXE 擴展名的外部命令</li><li>批處理文件</li></ol><h3 id="多個參數" tabindex="-1">多個參數 <a class="header-anchor" href="#多個參數" aria-label="Permalink to “多個參數”">​</a></h3><p>好的，選擇重新編寫 <code>TEST4.BAT</code> 文件來使一個命令可以獲取兩個參數，以便你可以看到這是如何工作的。首先，使用 <code>EDIT</code> 應用程序來創建一個簡單的名稱為 <code>FILE1.TXT</code> 的文本文件。在其中放置一段某種類型（例如，“Hello world”）的語句，並在你的 <code>TEMP</code> 工作目錄中保存文件。</p><p>接下來，使用 <code>EDIT</code> 來更改你的 <code>TEST4.BAT</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>COPY %1 %2</span></span>
<span class="line"><span>DIR</span></span></code></pre></div><p>保存它，然後執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP\\&gt;TEST4 FILE1.TXT FILE2.TXT</span></span></code></pre></div><p>在運行你的批處理文件時，你會看一個你的 <code>TEMP</code> 目錄的目錄列表。在列出的文件之中，你有 <code>FILE1.TXT</code> 和 <code>FILE2.TXT</code> ，它們是由你的批處理文件所創建的。</p><h3 id="嵌套批處理文件" tabindex="-1">嵌套批處理文件 <a class="header-anchor" href="#嵌套批處理文件" aria-label="Permalink to “嵌套批處理文件”">​</a></h3><p>批處理文件的另一個功能是能夠 “嵌套” ，這意味着一個批處理文件可以在另外一個批處理文件中被調用和運行。為查看這是如何工作的，從一對簡單的批處理文件開始：</p><p>第一個文件被稱為 <code>NBATCH1.BAT</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@ECHO OFF</span></span>
<span class="line"><span>ECHO Hello</span></span>
<span class="line"><span>CALL NBATCH2.BAT </span></span>
<span class="line"><span>ECHO world</span></span></code></pre></div><p>第一行 （<code>@ECHO OFF</code>） 輕輕地告訴批處理文件在你運行它時僅顯示命令 （而不是命令本身） 的輸出。你可能會在前面的示例中注意到這裏有很多關於批處理文件正在做什麼的反饋；在這種情況下，你正在允許你的批處理文件僅顯示結果。</p><p>第二個批處理被稱為 NBATCH2.BAT ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo from FreeDOS</span></span></code></pre></div><p>使用 <code>EDIT</code> 來創建這兩個文件，並在你的 TEMP 子目錄中保存它們。運行 <code>NBATCH1.BAT</code> 來查看會發生什麼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP\\&gt;NBATCH1.BAT </span></span>
<span class="line"><span>Hello</span></span>
<span class="line"><span>from FreeDOS</span></span>
<span class="line"><span>world</span></span></code></pre></div><p>你的第二個批處理文件將在第一個批處理文件之中通過 <code>CALL</code> 命令來執行，它將提供在你 “Hello world” 信息中間的字符串 “from FreeDOS” 。</p><h3 id="freedos-腳本" tabindex="-1">FreeDOS 腳本 <a class="header-anchor" href="#freedos-腳本" aria-label="Permalink to “FreeDOS 腳本”">​</a></h3><p>編寫你自己的簡單程序來自動執行通常需要大量輸入的任務的批處理文件，是一種極好的方法。你使用的 FreeDOS 越多, 你將越熟悉它的命令，在你熟知命令後，在一個批處理文件中列出它們僅是一件使你的 FreeDOS 系統讓你生活輕鬆的事情。嘗試一下！</p><hr>`,47)),a("p",null,[s[13]||(s[13]=e("via: ",-1)),n(i,{href:"https://opensource.com/article/21/3/batch-files-freedos"},{default:l(()=>[...s[12]||(s[12]=[e("https://opensource.com/article/21/3/batch-files-freedos",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("作者：",-1)),n(i,{href:"https://opensource.com/users/ahuka"},{default:l(()=>[...s[14]||(s[14]=[e("Kevin O'Brien",-1)])]),_:1}),s[19]||(s[19]=e(" 選題：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[15]||(s[15]=[e("lujun9972",-1)])]),_:1}),s[20]||(s[20]=e(" 譯者：[robsean]](",-1)),n(i,{href:"https://github.com/robsean"},{default:l(()=>[...s[16]||(s[16]=[e("https://github.com/robsean",-1)])]),_:1}),s[21]||(s[21]=e(") 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[22]||(s[22]=[e("LCTT",-1)])]),_:1}),s[25]||(s[25]=e(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...s[23]||(s[23]=[e("Linux中國",-1)])]),_:1}),s[26]||(s[26]=e(" 榮譽推出",-1))])])}const S=p(h,[["render",c]]);export{E as __pageData,S as default};
